AP4_Result CreateAtom(AP4_ByteStream& stream, AP4_UI32 type, AP4_Boolean force_64, AP4_UI64 size_64, AP4_Atom*& atom) {
    switch (type) {
        case AP4_ATOM_TYPE_MOOF:
            atom = new AP4_MoofAtom(size_64, *this);
            break;
        case AP4_ATOM_TYPE_MDAT:
            atom = new AP4_MdatAtom(size_64);
            break;
        default: {
            // Try external type handlers
            AP4_List<TypeHandler>::Item* handler_item = m_TypeHandlers.FirstItem();
            while (handler_item) {
                TypeHandler* handler = handler_item->GetData();
                if (AP4_SUCCEEDED(handler->CreateAtom(type, size_64, stream, GetContext(), atom))) {
                    break;
                }
                handler_item = handler_item->GetNext();
            }
            if (!atom) {
                return AP4_ERROR_INVALID_ATOM_TYPE;
            }
            break;
        }
    }
    return AP4_SUCCESS;
}
```

